def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    bal: dict[str, int] = {}
    frozen: set[str] = set()
    hist: list[tuple] = []
    rejected: list[int] = []
    digits = set("0123456789")

    def num(s: str):
        if not s or any(c not in digits for c in s):
            return None
        return int(s)

    for i, op in enumerate(ops):
        t = op.split(" ")
        v = t[0]
        ok = False
        rec = None

        if v == "open" and len(t) == 3:
            a, n = t[1], num(t[2])
            if n is not None and a not in bal:
                bal[a] = n
                rec = ("open", a)
                ok = True

        elif v == "deposit" and len(t) == 3:
            a, n = t[1], num(t[2])
            if n is not None and n > 0 and a in bal:
                rec = ("bal", a, bal[a])
                bal[a] += n
                ok = True

        elif v == "withdraw" and len(t) == 3:
            a, n = t[1], num(t[2])
            if n is not None and n > 0 and a in bal and a not in frozen and bal[a] >= n:
                rec = ("bal", a, bal[a])
                bal[a] -= n
                ok = True

        elif v == "transfer" and len(t) == 4:
            a, b, n = t[1], t[2], num(t[3])
            if (n is not None and n > 0 and a != b and a in bal and b in bal
                    and a not in frozen and bal[a] >= n):
                rec = ("tr", a, bal[a], b, bal[b])
                bal[a] -= n
                bal[b] += n
                ok = True

        elif v == "freeze" and len(t) == 2:
            a = t[1]
            if a in bal and a not in frozen:
                frozen.add(a)
                rec = ("frz", a, False)
                ok = True

        elif v == "unfreeze" and len(t) == 2:
            a = t[1]
            if a in bal and a in frozen:
                frozen.discard(a)
                rec = ("frz", a, True)
                ok = True

        elif v == "undo" and len(t) == 1:
            if hist:
                r = hist.pop()
                if r[0] == "open":
                    del bal[r[1]]
                    frozen.discard(r[1])
                elif r[0] == "bal":
                    bal[r[1]] = r[2]
                elif r[0] == "tr":
                    bal[r[1]] = r[2]
                    bal[r[3]] = r[4]
                elif r[0] == "frz":
                    if r[2]:
                        frozen.add(r[1])
                    else:
                        frozen.discard(r[1])
                ok = True

        if ok:
            if rec is not None:
                hist.append(rec)
        else:
            rejected.append(i)

    return bal, rejected
